// Door occupancy uses region_1. Keep the existing separate region_1 lights/AC branch.
var data=msg.payload;
if(!data||typeof data!=='object')return null;
var eui=String(msg.deveui||'').trim().toUpperCase();
if(eui!=='24E124443F431957')return [msg,null];
var now=Date.now(),event=null;
if(Object.prototype.hasOwnProperty.call(data,'region_1')){
    var occ=data.region_1;
    if(occ==='occupied'||occ==='vacant'){
        var record={eui:eui,value:occ,updatedAt:now,source:'region_1'};
        flow.set('vs321_occupancy',record);
        data.occupancy=occ;data.state=occ==='occupied'?'on':'off';
    }else{
        flow.set('vs321_occupancy',null);
        data.occupancy=null;data.state=null;
    }
    event={topic:'occupancy_update',deveui:eui,payload:{occupancy:data.occupancy,source:'region_1'}};
}
var all=global.get('milesight_devices')||{},previous=all[eui]||{};
all[eui]=Object.assign({},previous,msg.deviceMeta,{updatedAt:now,payload:Object.assign({},previous.payload||{},data)});
global.set('milesight_devices',all);
return [msg,event];

// Outputs stay: OPEN, CLOSE, timer, accepted_tap, log. No physical state claims.
// First hour is guaranteed; after that fresh region_1 vacant ends the cycle.
var s=context.get('runtime');
if(!s||s.version!==2)s={version:2,active:false,phase:'idle',generation:0};
var now=Date.now(),out=[null,null,null,null,null];
function occupancy(){
    var config=flow.get('automation_config')||{},rec=flow.get('vs321_occupancy');
    var age=(config.occupancyMaxAgeMinutes||15)*60000;
    if(!rec||rec.source!=='region_1'||rec.eui!==(config.occupancyEui||'24E124443F431957')||
       !Number.isFinite(rec.updatedAt)||rec.updatedAt>now||now-rec.updatedAt>age)return 'unknown';
    return rec.value==='occupied'||rec.value==='vacant'?rec.value:'unknown';
}
function token(){s.generation++;s.token=String(context.get('session'))+':'+s.generation;}
function log(event){out[4]={topic:'automasi/pintu',payload:{event:event,phase:s.phase,
    active:s.active,deadline:s.deadline||null,occupancy:occupancy(),physical_state_confirmed:false}};}
function resetTimer(){s.deadline=null;out[2]={reset:true};}
function arm(phase,duration){
    s.phase=phase;token();s.deadline=now+duration;
    out[2]=[{reset:true},{topic:'door_due',cycle:s.token,payload:'arm',delay:duration}];
}
function idle(){s.active=false;s.phase='idle';s.token=null;s.action=null;s.closeAfterOpen=false;s.finishAfterClose=false;resetTimer();}
function command(action){
    token();resetTimer();s.action=action;s.phase=action.indexOf('open_')===0?'open_pending':'close_pending';
    if(s.phase==='close_pending')s.finishAfterClose=action==='close_finish';
    var open=s.phase==='open_pending';
    out[open?0:1]={topic:'automasi/pintu/'+(open?'open':'close'),
        doorCycle:s.token,doorAction:action,payload:{state:open?'on':'off'}};
}
function decideClosed(){
    var occ=occupancy();
    if(occ==='occupied'){command('open_extended');log('occupied region_1: minta OPEN tambahan 120 menit');}
    else if(occ==='vacant'){idle();log('vacant region_1: selesai; tidak meminta OPEN lagi');}
    else{s.phase='waiting_occupancy';resetTimer();log('CLOSE sudah diterima; menunggu region_1 baru tanpa membuka');}
}
if(msg.topic==='manual_off'||msg.topic==='door_close'){
    if(s.phase==='open_pending'){
        s.closeAfterOpen=true;log('CLOSE manual: menunggu hasil OPEN yang sedang berjalan agar urutan perintah tetap');
    }else{command('close_finish');log('CLOSE manual: menunggu balasan; siklus dibatalkan');}
}else if(msg.topic==='door_result'){
    if(msg.doorCycle!==s.token||msg.doorAction!==s.action||
       (s.phase!=='open_pending'&&s.phase!=='close_pending'))return out;
    var reply=msg.payload||{},expected=s.phase==='open_pending'?'alwaysOpen':'close';
    if(reply.command!==expected)return out;
    if(reply.accepted!==true){
        s.active=false;s.phase='fault';s.action=null;resetTimer();
        log('Perintah pintu gagal/timeout; keadaan fisik belum diketahui; tidak mengulang otomatis');
    }else if(s.phase==='open_pending'&&s.closeAfterOpen){
        s.closeAfterOpen=false;command('close_finish');log('OPEN selesai: jalankan CLOSE yang menunggu');
    }else if(s.action==='open_initial'){
        arm('open_initial',60*60000);s.action=null;
        log('OPEN diterima ISAPI: mulai 1 jam pertama; vacant belum mengakhiri periode ini');
    }else if(s.action==='open_extended'){
        if(s.closeAfterOpen||occupancy()==='vacant'){
            s.closeAfterOpen=false;command('close_finish');log('vacant saat menunggu OPEN: minta CLOSE');
        }else{arm('open_extended',120*60000);s.action=null;log('OPEN diterima ISAPI: tambahan maksimum 120 menit');}
    }else if(s.action==='close_finish'||s.finishAfterClose||occupancy()==='vacant'){
        idle();log('CLOSE diterima ISAPI: siklus selesai; menunggu tap baru');
    }else{
        arm('closed_gap',2*60000);s.action=null;
        log('CLOSE diterima ISAPI: jeda 2 menit sebelum pemeriksaan berikutnya');
    }
}else if(msg.topic==='door_due'&&s.active&&msg.cycle===s.token&&now>=s.deadline){
    if(s.phase==='open_initial'||s.phase==='open_extended'){
        command(occupancy()==='vacant'?'close_finish':'close_gap');
        log('Periode OPEN selesai: minta CLOSE dahulu; belum membuka ulang');
    }else if(s.phase==='closed_gap')decideClosed();
}else if(msg.topic==='occupancy_update'&&s.active){
    var occ=occupancy();
    if(s.phase==='open_extended'&&occ==='vacant'){
        command('close_finish');log('vacant region_1: langsung minta CLOSE pada periode tambahan');
    }else if(s.phase==='open_pending'&&s.action==='open_extended'&&occ==='vacant'){
        s.closeAfterOpen=true;log('vacant: menunggu hasil OPEN yang sedang berjalan sebelum CLOSE');
    }else if(s.phase==='close_pending'&&occ==='vacant'){
        // Keep the outstanding request identity; its ACK ends rather than reopens.
        s.finishAfterClose=true;
    }else if(s.phase==='closed_gap'&&occ==='vacant'){
        idle();log('vacant saat jeda CLOSE: siklus selesai tanpa membuka ulang');
    }else if(s.phase==='waiting_occupancy')decideClosed();
}else if(msg.topic==='tap'||(msg.payload&&msg.payload.state==='on')){
    if(s.active)log('tap berulang: tidak mereset timer dan tidak melewati jeda CLOSE');
    else{
        s.active=true;s.closeAfterOpen=false;s.finishAfterClose=false;
        command('open_initial');out[3]={topic:'accepted_tap',payload:{state:'on'}};
        log('tap awal: minta alwaysOpen; timer 1 jam dimulai setelah balasan diterima');
    }
}
context.set('runtime',s);
node.status({fill:s.phase==='fault'?'red':s.active?'green':'grey',shape:s.phase==='waiting_occupancy'?'ring':'dot',
    text:s.phase+(s.deadline?' sampai '+new Date(s.deadline).toLocaleTimeString():'')});
return out;

// Outputs 1..6 sama dengan flow lama. Output 7 menuju Dispatch kontrol web.
// RUANG_UTAMA A/B dan keputusan OFF AC memakai satu timer dan region_1.
// Output 8: OFF AC otomatis -> Function HVAC lama -> MQTT IRHVAC.
var s=context.get('runtime')||{active:false,waiting:false,generation:0};
var out=[null,null,null,null,null,null,null,null],now=Date.now();
function log(text){out[5]={topic:'automasi/lampu',payload:{event:text,active:s.active,waitingOccupancy:s.waiting,deadline:s.deadline||null,pauseUntil:s.pause?s.pause.until:null}};}
function occupancy(){
    var config=flow.get('automation_config')||{},rec=flow.get('vs321_lights_region1');
    var maxAge=(config.occupancyMaxAgeMinutes||15)*60000;
    if(!rec||rec.source!=='region_1'||rec.eui!==(config.occupancyEui||'24E124443F431957')||now-rec.updatedAt>maxAge||rec.updatedAt>now)return 'unknown';
    return rec.value;
}
function arm(duration){
    s.waiting=false;s.generation++;
    s.token=String(context.get('session'))+':'+s.generation;
    s.deadline=now+duration;
    out[3]=[{reset:true},{topic:'lights_due',cycle:s.token,payload:'arm',delay:duration}];
}
function off(){
    s.active=false;s.waiting=false;s.deadline=null;s.token=null;s.pause=null;s.occupancyEligible=false;
    out[2]={payload:{state:'off'}};out[3]={reset:true};
}
function decide(){
    s.occupancyEligible=true;
    var occ=occupancy();
    if(occ==='vacant'){off();out[7]={topic:'automation_ac_off',payload:{state:'off'}};log('vacant region_1: RUANG_UTAMA A/B dan AC OFF');}
    else if(occ==='occupied'){arm(120*60000);log('occupied: tetap ON; cek lagi 120 menit');}
    else{s.waiting=true;log('menunggu occupancy VS321 baru');}
}
if(msg.topic==='web_override'&&msg.control){
    var p=msg.control;
    if(p.expires_at<=now)return out;
    var seen=flow.get('office_web_control_seen')||{};
    if(seen[p.id]){
        if(seen[p.id].device===p.device&&seen[p.id].state===p.state){msg.automation=seen[p.id].automation;out[6]=msg;}
        return out;
    }
    if(!s.pause)s.pause={remaining:s.active?Math.max(0,(s.deadline||now)-now):null};
    s.pause.until=now+60*60000;
    arm(60*60000);
    msg.automation={timer_paused:true,scope:'RUANG_UTAMA_A_B',pause_minutes:60,resume_at_utc:new Date(s.pause.until).toISOString(),remaining_seconds:s.pause.remaining===null?null:Math.ceil(s.pause.remaining/1000)};
    out[6]=msg;log('kontrol web: timer dibekukan 60 menit');
}else if(msg.topic==='manual_off'||msg.topic==='main_off'){
    off();if(msg.topic==='manual_off')out[4]={payload:{state:'off'}};
    log('OFF manual lokal; timer dan jeda web dibatalkan');
}else if(msg.topic==='accepted_tap'){
    out[1]={payload:{state:'on'}};
    if(!s.active){
        s.active=true;
        if(s.pause){s.pause.remaining=10*3600000;log('tap saat jeda web: timer 10 jam dimulai setelah jeda');}
        else{arm(10*3600000);out[0]={payload:{state:'on'}};log('tap awal: RUANG_UTAMA ON 10 jam');}
    }else log(s.pause?'tap berulang saat jeda; sisa timer tetap':'siklus aktif; timer 10 jam tetap');
}else if(msg.topic==='lights_due'&&msg.cycle===s.token&&now>=s.deadline){
    if(s.pause){
        var remaining=s.pause.remaining;
        s.pause=null;
        if(s.active&&remaining!==null){
            if(remaining>0){
                if(s.occupancyEligible&&occupancy()==='vacant')decide();
                else{out[0]={payload:{state:'on'}};arm(remaining);log('jeda web selesai: kembali ON, lanjut sisa timer');}
            }
            else{
                if(occupancy()!=='vacant')out[0]={payload:{state:'on'}};
                decide();
            }
        }else{s.deadline=null;s.token=null;s.waiting=false;log('jeda web selesai; tidak ada siklus MinMoe aktif');}
    }else if(s.active)decide();
}else if(msg.topic==='occupancy_update'&&s.active&&!s.pause&&
    (s.waiting||(s.occupancyEligible&&occupancy()==='vacant')))decide();
context.set('runtime',s);
node.status({fill:s.pause?'yellow':s.active?'green':'grey',shape:s.waiting?'ring':'dot',text:s.pause?'jeda web sampai '+new Date(s.pause.until).toLocaleTimeString():s.active?(s.waiting?'ON / menunggu occupancy':'ON sampai '+new Date(s.deadline).toLocaleTimeString()):'tidak ada timer aktif'});
return out;

// Send verified ACK/timeout to the door controller and the existing Debug output.
var pending=flow.get('door_bridge_pending')||{};
var timedOut=msg.payload==='ack_timeout',data=timedOut?null:msg.payload;
var id=timedOut?msg.bridgeRequestId:data&&data.id,request=pending[id];
if(!request)return [{payload:{accepted:false,id:id||null,error:'Balasan terlambat/tidak memiliki request aktif'}},null];
if(!timedOut&&data.command!==request.command)return [{payload:{accepted:false,id:id,error:'Perintah pada balasan tidak cocok'}},null];
delete pending[id];flow.set('door_bridge_pending',pending);
if(timedOut)data={id:id,command:request.command,accepted:false,error:'Tidak ada respons dalam 30 detik; keadaan pintu belum terkonfirmasi'};
node.status({fill:data.accepted?'green':'red',shape:timedOut?'ring':'dot',text:data.command+(data.accepted?' diterima ISAPI':' gagal/belum terkonfirmasi')});
return [{topic:'door_result',doorCycle:request.doorCycle,doorAction:request.doorAction,payload:data},
    timedOut?null:{topic:id,reset:true}];

// Preserve TCP protocol; attach cycle metadata only to the local pending cache.
var xml=String(msg.payload||'');
var match=xml.match(/<cmd>\s*(alwaysOpen|close)\s*<\/cmd>/);
if(!match){node.error('Perintah pintu tidak dikenali',msg);return null;}
var seq=(context.get('seq')||0)+1;context.set('seq',seq);
var id=context.get('session')+'-'+seq;
var pending=flow.get('door_bridge_pending')||{};
pending[id]={command:match[1],sentAt:Date.now(),doorCycle:msg.doorCycle||null,doorAction:msg.doorAction||null};
flow.set('door_bridge_pending',pending);
return [
    {payload:JSON.stringify({type:'door_command',id:id,command:match[1]})+'\n'},
    {topic:id,bridgeRequestId:id,payload:'wait'}
];

// Read the existing power and observed energy-counter cache only. No SQL or control commands.
var now=Date.now(),cache=flow.get('telemetry_latest_v1')||{};
var meters=["24E124148060C6A0","24E12414806031FC","24E124148060D73E","24E1241480609886","24E1247710630110","24E124771063F466","24E1247710633F88","24E1247710638799"];
var records=meters.map(function(eui){
    var entry=(cache[eui]||{}).power_w;
    // Retain each last actual value; backend marks old observations as previous.
    var valid=entry&&typeof entry.value==='number'&&Number.isFinite(entry.value)&&entry.value>=0&&entry.value<=4294967295&&Number.isFinite(entry.receivedAt)&&entry.receivedAt<=now;
    var energy=(cache[eui]||{}).energy_minute_points;
    var points=Array.isArray(energy)?energy.filter(function(p){return p&&Number.isFinite(p.at)&&p.at<=now&&now-p.at<=2700000&&Number.isFinite(p.wh)&&p.wh>=0&&p.wh<=4294967295;}).slice(-16).map(function(p){return {at:new Date(p.at).toISOString(),wh:p.wh};}):[];
    return {device_eui:eui,power_w:valid?entry.value:null,power_w_at:entry&&Number.isFinite(entry.receivedAt)&&Number.isFinite(new Date(entry.receivedAt).getTime())?new Date(entry.receivedAt).toISOString():null,energy_points:points};
});
return {topic:'office1/monitoring/power',qos:'0',retain:true,payload:JSON.stringify({type:'office_power',version:1,source_id:'ug65-ussc',sampled_at_utc:new Date(now).toISOString(),interval_minutes:1,records:records})};
